/**
 * Exo Jacobi-1D driver: mirrors PolyBench/C jacobi-1d.c but calls the Exo-generated kernel.
 */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "jacobi-1d.h"

/* Include the Exo-generated kernel header. */
#include "generated/jacobi-1d/jacobi-1d.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_1D(A,N,n),
		 DATA_TYPE POLYBENCH_1D(B,N,n))
{
  int i;

  for (i = 0; i < n; i++)
    {
      A[i] = ((DATA_TYPE) i + 2) / n;
      B[i] = ((DATA_TYPE) i + 3) / n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(A,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    {
      if (i % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Baseline Jacobi-1D kernel: straightforward two-phase time stepping.
@proc
def kernel_jacobi_1d_base(
    tsteps: size,
    n: size,
    A: DATA_TYPE[n] @ DRAM,
    B: DATA_TYPE[n] @ DRAM,
):
    # Need at least three points so that neighbors i-1 and i+1 are valid.
    assert n > 2

    for t in seq(0, tsteps):
        # First half-step: update B from A.
        for i in seq(1, n - 1):
            B[i] = 0.33333 * (A[i - 1] + A[i] + A[i + 1])

        # Second half-step: update A from B.
        for i in seq(1, n - 1):
            A[i] = 0.33333 * (B[i - 1] + B[i] + B[i + 1])


# ---------------------------------------------------------------------------
# Scheduling: exploit data-parallelism in the spatial dimension.
# Each iteration of the inner loops over i writes to a distinct element and
# only reads from neighboring points in the *other* array for the same time
# step. There are therefore no loop-carried dependencies in i, and we can
# safely parallelize these loops.
# This lowers to OpenMP pragmas in the generated C.
# ---------------------------------------------------------------------------

kernel_jacobi_1d_sched = kernel_jacobi_1d_base

# Parallelize the first spatial loop (updating B from A).
loop_i_B = kernel_jacobi_1d_sched.find_loop("i #0")
kernel_jacobi_1d_sched = parallelize_loop(kernel_jacobi_1d_sched, loop_i_B)

# Parallelize the second spatial loop (updating A from B).
loop_i_A = kernel_jacobi_1d_sched.find_loop("i #1")
kernel_jacobi_1d_sched = parallelize_loop(kernel_jacobi_1d_sched, loop_i_A)

# Perform a final simplification pass (purely structural clean-up).
kernel_jacobi_1d_sched = simplify(kernel_jacobi_1d_sched)

# Export the scheduled kernel under the name expected by the C driver.
kernel_jacobi_1d = rename(kernel_jacobi_1d_sched, "kernel_jacobi_1d")
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(A, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(B, DATA_TYPE, N, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 1D views to 1D pointers. */
  kernel_jacobi_1d (/*ctxt=*/NULL,
                    tsteps, n,
                    (DATA_TYPE*)POLYBENCH_ARRAY(A),
                    (DATA_TYPE*)POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}

